mapper.insert:
INSERT INTO agent_idempotency_record (
    id, user_id, operation, idempotency_key, request_hash,
    status, response_status, response_body, resource_type, resource_id,
    created_at, expires_at
) VALUES (
    #{id}, #{userId}, #{operation}, #{idempotencyKey}, #{requestHash},
    #{status}, #{responseStatus}, #{responseBody}, #{resourceType}, #{resourceId},
    NOW(3), #{expiresAt}
)

mapper.select:
SELECT * FROM agent_idempotency_record
WHERE user_id = #{userId}
  AND operation = #{operation}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1

mapper.delete:
DELETE FROM agent_idempotency_record
WHERE expires_at < #{before}
LIMIT 1000
